    ["04-47"] = {steps={[1]={npc="Arathandris Silversky", tgt="Arathandris Silversky"}, [2]={npc="Grifleur", tgt="Grifleur"}, [3]={npc="Greta Mosshoof", tgt="Greta Mosshoof"}, [4]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [5]={npc="Taronn Redfeather", tgt="Taronn Redfeather", tag="Facultatif"}, [6]={hint="Grifleur veut que vous prouviez votre valeur en tuant 6 Guerriers Mort-bois, 6 Guides Mort-bois et 6 Jardiniers Mort-bois. Lorsque ce sera fait, retournez le voir dans le sud de Gangrebois, près du Sanctuaire d'émeraude."}, [7]={npc="Grifleur", tgt="Grifleur"}, [8]={npc="Grifleur", tgt="Grifleur"}, [9]={hint="Tuer 11 Liges de la corruption Jadefeu, 9 Traqueurs des ombres Jadefeu, 9 Voleurs Jadefeu et Xavathras. Retourner voir Eridan Bluewind, à Gangrebois, quand la mission est terminée."}, [10]={hint="Entrer dans Jaedenar et tuer 4 Molosses de Jaedenar, 4 Gardiens de Jaedenar, 6 Adeptes de Jaedenar, et 6 Sectateurs de Jaedenar avant de retourner auprès de Greta Mosshoof dans Gangrebois."}, [11]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [12]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [13]={npc="Greta Mosshoof", tgt="Greta Mosshoof"}, [14]={npc="Greta Mosshoof", tgt="Greta Mosshoof"}, [15]={hint="Amener la Gourde vide au Puits de lune au centre de Jaedenar et la remplir avant de retourner voir Greta Mosshoof dans Gangrebois."}, [17]={hint="Trouver et détruire 2 Bêtes d'entropie et 2 Horreurs d'entropie tout en explorant le Val Grêlé. Après avoir vérifié que les cratères à cet endroit sont toujours remplis d'eau corrompue, retourner auprès de Taronn Redfeather dans Gangrebois.", tag="Facultatif"}, [18]={hint="Eridan Bluewind de Gangrebois veut que vous tuiez 8 Implorateurs de l'enfer Jadefeu, 8 Traîtres Jadefeu, 8 Entourloupeurs Jadefeu, et Xavaric. Revenir auprès d'Eridan quand la tâche est accomplie."}, [19]={npc="Flûte de Xavaric", npcObj=true}, [20]={hint="Apporter la Flûte de Xavaric et 5 échantillons de Lien maudit Jadefeu à Eridan Bluewind, dan