    [4141] = {n="Muigin et Larion", d="Récolter 15 Pétales-de-sang et retourner voir Muigin.", tgo={{"Flagellant Pétale-de-sang", "Ecorcheur Pétale-de-sang", "Batteur Pétale-de-sang", "Trappeur Pétale-de-sang"}}},
    [4142] = {n="Visite à Gregan", d="Apporter une Pétale-de-sang à Gregan Brewspewer en Feralas."},
    [4161] = {n="Une recette kaldorei", d="Collecter 7 Petites pattes d'araignée pour Zarrin, à Dolanaar.", tgo={{"Araignée forestière", "Araignée minière", "Mère Croc", "Rôdeuse des falaises", "Rôdeuse des bois", "Rôdeuse des forêts", "Tisse-nuit vicieuse", "Rôdeuse des sous-bois"}}},
    [4182] = {n="La menace des draconiens", d="Tuer 15 Rejetons noirs, 10 Draconides noirs, 4 Wyrmides noirs et 1 Drake noir. Retrouver Helendis Riverhorn une fois la tâche accomplie.", tgo={{"Rejeton noir"}, {"Draconide noir"}, {"Drake noir"}, {"Wyrmide noir"}}},
    [4183] = {n="Les véritables maîtres", d="Voyager jusqu'à Comté-du-Lac et remettre la Lettre d'Helendis Riverhorn au Magistrat Solomon."},
    [4184] = {n="Les véritables maîtres", d="Voyager vers Hurlevent et remettre la Demande d'aide de Solomon au généralissime Bolvar Fordragon.\nBolvar demeure dans le Donjon de Hurlevent."},
    [4185] = {n="Les véritables maîtres", d="Parler au généralissime Bolvar Fordragon après avoir parlé à dame Katrana Prestor.", tgo={{"Dame Katrana Prestor"}}},
    [4186] = {n="Les véritables maîtres", d="Apporter le Décret de Bolvar au Magistrat Solomon à Comté-du-Lac."},
    [4223] = {n="Les véritables maîtres", d="Parler au maréchal Maxwell dans les Steppes ardentes."},
    [4224] = {n="Les véritables maîtres", d="Parlez à John le Loqueteux pour apprendre ce qu'il est advenu du maréchal Windsor puis retournez voir le maréchal Maxwell lorsque vous aurez accompli cette tâche.\nVous vous rappelez que le maréchal Maxwell vous a dit de le chercher dans une grotte au nord.", tgo={{"John le Loqueteux"}}},
    [4241] = {n="Maréchal Windsor", d="Partir pour le mont Rochenoire au nord-ouest et pénétrer dans les Profondeurs de Rochenoire. Découvrir ce qu'il est advenu du Maréchal Windsor.\nVous vous souvenez que John le Loqueteux a dit que Windsor avait été traîné en prison."},
    [4243] = {n="À la poursuite d'A-mi 01", d="Trouver A-mi 01 dans le Cratère d'Un'Goro."},
    [4244] = {n="À la poursuite d'A-mi 01", d="Trouver une Caisse en mithril et retourner près de A-mi 01 dans le Cratère d'Un'Goro.", tgo={{"Clonk", "Déchiqueteur Frostwolf", "Déchiqueteur Stormpike", "7:XT"}}},
    [4245] = {n="À la poursuite d'A-mi 01", d="Escorter A-mi 01 sur le chemin du retour jusqu'à Karna Remtravel dans le Cratère d'Un'Goro."},
    [4262] = {n="Grand seigneur Pyron", d="Tuer le Grand seigneur Pyron et retourner voir Jalinda Sprig.\nJalinda vous a dit qu'il gardait la carrière. Peut-être devriez-vous chercher à cet endroit ?", tgo={{"Grand seigneur Pyron"}}},
    [4265] = {n="L'évasion de la ruche", d="Libérer Raschal de la ruche de Zukk'ash.\nRevenir voir Ginro Hearthkindle au bastion de Feathermoon et lui dire que Raschal est sain et sauf."},
    [4266] = {n="Accueil d'un héros", d="Parler à Shandris Feathermoon dans le bastion de Feathermoon."},
    [4267] = {n="L'ascension des silithides", d="Apporter le Rapport de Raschal à Gracina Spiritmight à Darnassus."},
    [4283] = {n="CINQUANTE ! OUI !", d="Oralius veut 50 Médaillons de Rochenoire. Il y a de fortes chances de trouver ces médaillons sur les orcs des Steppes ardentes.", tgo={{"Soldat rochenoire", "Sorcier rochenoire", "Pourfendeur Blackrock", "Démoniste rochenoire", "Maître de guerre Blackrock", "Worg Blackrock", "Worg de braise", "Worg de braise écumant"}}},
    [4284] = {n="Cristaux de puissance", d="Récupérer 7 Cristaux de puissance de chaque couleur (rouge, bleu, jaune et vert). Les apporter à J.D. Collie au refuge des Marshal.", objs={"Cristal de puissance rouge", "Cristal de puissance jaune", "Cristal de puissance vert", "Cristal de puissance bleu"}},
    [4285] = {n="Le Pylône nord", d="Découvrir l'emplacement du Pylône de cristal nord dans le Cratère d'Un'Goro.", objs={"Pylône de cristal nord"}},
    [4286] = {n="Du beau matériel", d="Se rendre dans les Profondeurs de Rochenoire et trouver 20 Sacoches Sombrefer. Retourner voir Oralius lorsque vous aurez accompli cette tâche. Logiquement, ces sacoches devraient être sur les nains Sombrefer des Profondeurs de Rochenoire.", tgo={{"Surveillant Ragenclume", "Gardien Ragenclume", "Garde Ragenclume", "Fantassin Ragenclume", "Soldat Ragenclume", "Médecin Ragenclume", "Officier Ragenclume", "Paysan Ombreforge"}}},
    [4287] = {n="Le Pylône est", d="Trouver l'emplacement du Pylône de cristal est dans le Cratère d'Un'Goro.", objs={"Pylône de cristal est"}},
    [4288] = {n="Le Pylône ouest", d="Découvrir l'emplacement du Pylône de cristal ouest.", objs={"Pylône de cristal ouest"}},
    [4289] = {n="Les gorilles d'Un'Goro", d="Apporter 2 Peaux de gorille d'Un'Goro, 2 Peaux de marteleur d'Un'Goro et 2 Peaux de foudroyeur d'Un'Goro à Torwa Pathfinder à l'entrée du cratère d'Un'Goro.", tgo={{"Gorille d'Un'Goro", "Gorille d'Un'Goro"}, {"Marteleur d'Un'Goro"}, {"Foudroyeur d'Un'Goro"}}},
    [4290] = {n="La nourriture de Lar'korwi", d="Trouver la dernière victime de Lar'korwi et voler un Morceau de carcasse d'un battrodon, puis retourner voir Torwa Pathfinder au Cratère d'Un'Goro.", objs={"Carcasse fraîche de battrodon"}},
    [4291] = {n="Un parfum pour Lar'korwi", d="Apporter 2 Glandes de phéromone de ravasaure à Torwa Pathfinder près de l'entrée du Cratère d'Un'Goro.", tgo={{"Compagne de Lar'korwi"}}},
    [4292] = {n="Un appât pour Lar'korwi", d="En utilisant le contenu de la Sacoche de Torwa, appeler Lar'korwi et le vaincre. Puis apporter la Tête de Lar'korwi à Torwa Pathfinder près de l'entrée du Cratère d'Un'Goro.", tgo={{"Lar'korwi"}}},
    [4296] = {n="Tablette des Sept", d="Apporter la Transcription de la tablette à Maxwort Uberglint dans les Steppes ardentes.", objs={"Tablette des Sept"}},
    [4301] = {n="Le puissant U'cha", d="Apporter la Peau d'U'cha à Torwa Pathfinder à l'entrée du Cratère d'Un'Goro.", tgo={{"U'cha"}}},
    [4321] = {n="Ceci explique cela", d="Parler à J.D. Collie dans un moment."},
    [4341] = {n="Kharan Mighthammer", d="Aller dans les Profondeurs de Rochenoire et trouver Kharan Mighthammer.\nLe roi a mentionné que Kharan était retenu prisonnier là-bas ; cherchez une prison."},
    [4421] = {n="La corruption des Jadefeu", d="Tuer 11 Liges de la corruption Jadefeu, 9 Traqueurs des ombres Jadefeu, 9 Voleurs Jadefeu et Xavathras. Retourner voir Eridan Bluewind, à Gangrebois, quand la mission est terminée.", tgo={{"Lige de la corruption Jadefeu"}, {"Traqueur des ombres Jadefeu"}, {"Voleur Jadefeu"}, {"Xavathras"}}},
    [4441] = {n="Anciens corrompus", d="Aller à Darnassus et utiliser la Fiole d'Eridan dans le Temple de la Lune, pour obtenir une Fiole d'eau bénite. Retourner voir Eridan avec la Fiole pleine.", objs={"Fontaine du temple de la Lune"}},
    [4442] = {n="Purifié !", d="Attendre un moment avant de reparler à Eridan."},
    [4449] = {n="Piégé !", d="Tuer 8 Géologues Sombrefer et rapporter 15 morceaux d'Etoffe de soie à la personne enfermée de les toilettes de la gorge des Vents brûlants.", tgo={{"Géologue Sombrefer"}, {}}, objs={"Granit d'Alterac", "Coffre en morceaux", "Coffre solide"}},
    [4450] = {n="Grand livre de Tanaris", d="Prendre la copie du Livre de Goodsteel, puis collecter les objets qui y sont listés avant d'aller voir Krinkle Goodsteel, à Tanaris.", tgo={{}, {"Araignée verrière"}, {}, {"Jarquia"}}, objs={"Livre de Goodsteel", "Caisse endommagée"}},
    [4491] = {n="Un peu d'aide de mes amis", d="Conduire Ringo à Spraggle Frock, au refuge des Marshal.\nSi Ringo s'évanouit, utiliser la Gourde de Spraggle pour le réanimer."},
    [4492] = {n="Perdu !", d="Trouver Ringo sur la crête de la Fournaise."},
    [4493] = {n="La marche des silithides", d="Parler à l'alchimiste Pestlezugg à Gadgetzan."},
    [4495] = {n="Un bon ami", d="Trouver Iverron près de la grotte au nord."},
    [4496] = {n="Fiasco dans la jungle", d="Apporter une Glande olfactive Gorishi et 5 Echantillons d'Humus d'Un'Goro à l'alchimiste Pestlezugg, à Gadgetzan.", tgo={{"Guêpe Gorishi", "Ouvrier Gorishi", "Ravageur Gorishi", "Dard Gorishi", "Tunnelière Gorishi", "Garde Gorishi", "Reine Gorishi"}, {}}, objs={"Tas de poussière d'Un'Goro"}},
    [4501] = {n="Attention aux pterreurdactyles", d="Tuer 10 Pterreurdactyles et 15 Pterreurdactyles frénétiques, puis parler à Spraggle Frock, au refuge des Marshal.", tgo={{"Pterreurdactyle"}, {"Pterreurdactyle frénétique"}}},
    [4502] = {n="Activité volcanique", d="Collecter 9 Echantillons de cendre Un'Goro sur les Elémentaires de brûlure qui se trouvent autour du volcan, dans le Cratère d'Un'Goro, puis les apporter à Liv Rizzlefix, à Ratchet.", tgo={{"Elémentaire de brûlure", "Brasier vivant", "Blazerunner", "Envahisseur flamboyant", "Baron Charr"}}},
    [4503] = {n="La machine volante de Shizzle", d="Apporter 8 Ecailles étoilées de dimeurtrodon et 8 Ecailles étoilées de pterreurdactyles à Shizzle, au refuge des Marshal.", tgo={{"Jeune dimeurtrodon", "Dimeurtrodon", "Ancien dimeurtrodon"}, {"Petit pterreurdactyle", "Pterreurdactyle", "Pterreurdactyle frénétique"}}},
    [4504] = {n="Ultra collant", d="Collecter 12 échantillons de Goudron ultra collant pour Tran'rek, à Gadgetzan.", tgo={{"Bête du goudron", "Rôdeur du goudron", "Seigneur du goudron", "Rampeur du goudron"}}},
    [4581] = {n="Kayneth Stillwind", d="Apporter la Note de Shindrell à Kayneth Stillwind au Chant des Forêts."},
    [4681] = {n="Échouage", d="Récupérer les Restes de tortue de mer sur le Squelette de la tortue de mer, dans les eaux à l'ouest d'Auberdine, puis parler à Gwennyth Bly'Leggonde, à Auberdine.", objs={"Squelette de tortue de mer"}},
    [4722] = {n="La tortue de mer échouée", d="Apporter les Restes de tortue de mer à Gwennyth Bly'Leggonde à Auberdine."},
    [4723] = {n="La créature marine échouée", d="Apporter les Os de créature marine à Gwennyth Bly'Leggonde à Auberdine."},
    [4725] = {n="La tortue de mer échouée", d="Apporter la Boîte aux marques étranges à Gwennyth Bly'Leggonde à Auberdine."},
    [4726] = {n="L'essence de rejeton", d="Apporter 8 Essences de Rejeton et le Draco-Incarcinatrix 900 à Tinkee Steamboil à la Corniche des flammes dans les Steppes ardentes.", objs={"Essence de rejeton"}},
    [4727] = {n="La tortue de mer échouée", d="Apporter les Restes de tortue de mer à Gwennyth Bly'Leggonde à Auberdine."},
    [4728] = {n="La créature marine échouée", d="Apporter les Os de créature marine à Gwennyth Bly'Leggonde à Auberdine."},
    [4730] = {n="La créature marine échouée", d="Apporter les Os de créature marine à Gwennyth Bly'Leggonde à Auberdine."},
    [4731] = {n="La tortue de mer échouée", d="Apporter la Boîte aux marques étranges à Gwennyth Bly'Leggonde à Auberdine."},
    [4732] = {n="La tortue de mer échouée", d="Apporter les Restes de tortue de mer à Gwennyth Bly'Leggonde à Auberdine."},
    [4733] = {n="La créature marine échouée", d="Apporter les Os de créature marine à Gwennyth Bly'Leggonde à Auberdine."},
    [4740] = {n="On recherche : Fondeboue !", d="Trouver et tuer le murloc connu sous le nom de Fondeboue. On pense que la créature défend les huttes des murlocs au sud d'Auberdine près de l'eau.\nAnnoncer la mort de Fondeboue à la Sentinelle Glynda Nal'Shea à Auberdine.", tgo={{"Fondeboue"}}},
    [4761] = {n="Thundris Windweaver", d="Parler à Thundris Windweaver, à Auberdine."},
    [4762] = {n="La Bondissante", d="Aller au nord d'Auberdine, à la première chute d'eau, le long de la Bondissante et prélever un échantillon de l'eau de l'étang.\nRetourner voir Thundris Windweaver, à Auberdine, avec le Prélèvement de la Bondissante.", objs={"Cliffspring River Waterfall"}},
    [4763] = {n="La corruption des Noirbois", d="Remplir le Bol de purification vide au Puits de lune d'Auberdine.\nCollecter un échantillon de fruit, de noix et de céréales dans les camps nord des furbolgs Noirbois.\nMélanger les échantillons de nourriture à l'eau du bol et le placer à proximité du feu le plus proche de la rivière Bondissante, au camp nord. Cela fera venir le satyre corrupteur.\nPrendre son Talisman de corruption et l'apporter à Thundris Windweaver, à Auberdine.", objs={"Sac des démons de Xabraxxis"}},
    [4811] = {n="Le cristal rouge", d="Voyager en direction de l'est en partant d'Auberdine et chercher un gros cristal rouge le long de la chaîne de montagne est de Sombrivage. Aller faire un rapport de ce que vous avez trouvé à la Sentinelle Glynda Nal'Shea à Auberdine.", objs={"Mystérieux Cristal rouge"}},
    [4812] = {n="Comme l'eau tombe en cascade", d="Remplir le Tube d'eau vide au Puits de lune d'Auberdine, puis chercher le cristal rouge le long des falaises des montagnes à l'est de Sombrivage.", objs={"Puits de lune d'Auberdine"}},
    [4813] = {n="Les fragments à l'intérieur", d="Aller faire un rapport de ce que vous avez trouvé à la Sentinelle Glynda Nal'Shea à Auberdine."},
    [4842] = {n="Sources étranges", d="Suivre les instructions de Donova Snowden, puis faire un rapport."},
    [4861] = {n="Les Indomptables enragés", d="Localiser le camp démoli et les fournitures de Jaron Stoneshaper, au sud du Berceau-de-l'Hiver."},
    [4863] = {n="Les Indomptables enragés", d="Trouver le chariot saccagé de Jaron Stoneshaper."},
    [4864] = {n="Les Indomptables enragés", d="Ramasser les Fournitures de Jaron dans la neige, puis trouver l'Indomptable qui a volé l'amulette dont Jaron a parlé.\nRapporter les fournitures de Jaron et l'Amulette de la plume bleue à Jaron Stoneshaper au pavillon, dans le Berceau-de-l'Hiver.", tgo={{}, {"Chouettard affolé", "Chouettard lunaire", "Chouettard berserk", "Gardien d'Elune"}}, objs={"Fournitures de Jaron"}},
    [4901] = {n="Les gardiens de l'autel", d="Protéger Ranshalla pendant qu'elle s'efforce de réactiver l'Autel d'Elune. Faire un rapport de vos découvertes à Erelas Ambersky, au village de Rut'theran."},
    [4902] = {n="Les Indomptables d'Elune", d="Parler à l'archidruide Fandral Staghelm, à Darnassus."},
    [4906] = {n="Plus de corruption", d="Eridan Bluewind de Gangrebois veut que vous tuiez 8 Implorateurs de l'enfer Jadefeu, 8 Traîtres Jadefeu, 8 Entourloupeurs Jadefeu, et Xavaric. Revenir auprès d'Eridan quand la tâche est accomplie.", tgo={{"Implorateur de l'enfer Jadefeu"}, {"Traître Jadefeu"}, {"Entourloupeur Jadefeu"}, {"Xavaric"}}},
    [4971] = {n="Une question de temps", d="Utiliser le Déplaceur temporel à côté de l'un des silos d'Andorhal pour révéler des Parasites temporels.\nTuer 15 Parasites temporels et rapporter le Déplaceur temporel à Chromie, à l'auberge d'Andorhal, dans les Maleterres de l'ouest.", tgo={{"Parasite temporel"}}},
    [4984] = {n="La faune et la flore souffrent aussi", d="Détruire 8 Loups malades, puis retourner voir Mulgris Deepriver, au Repaire putride dans les Maleterres de l'ouest.", tgo={{"Loup malade"}}},
    [4985] = {n="La faune et la flore en souffrent aussi", d="Détruire 8 Grizzlis malades, puis retourner voir Mulgris Deepriver au Repaire putride, dans les Maleterres de l'ouest.", tgo={{"Grizzly malade"}}},
    [4986] = {n="La branche de chêne à glyphes", d="D'après la magie contenue dans la Branche de chêne à glyphes, le druide tauren voulait qu'elle soit apportée au Cercle cénarien, à Darnassus. Aller solliciter l'assistance de l'un des druides, là-bas."},
    [5021] = {n="Mieux vaut tard que jamais", d="Le discours incohérent de la femme fantomatique indique qu'elle a besoin qu'on livre un colis pour elle. Elle a dit que le colis se trouvait là où se trouve son cheval. Le fantôme est incompréhensible lorsqu'il s'agit de préciser où se trouve son cheval ou l'endroit où le paquet doit être livré."},
    [5022] = {n="Mieux vaut tard que jamais", d="Rendre visite aux Facteurs royaux de Stormwind pour apprendre l'adresse d'une certaine Emma Felstone. En général, il y a un officier du recensement à l'Hôtel de ville."},
    [5048] = {n="Emma la bonne pâte", d="Trouver la vieille Emma à Stormwind, et découvrir si elle est en fait Emma Felstone. Si c'est le cas, elle appréciera peut-être le colis que Janice Felstone lui a préparé."},
    [5050] = {n="Charme porte-bonheur", d="Rapporter son Demi-charme porte-bonheur à Janice Felstone dans les Maleterres de l'ouest."},
    [5066] = {n="Un appel aux armes : les Maleterres", d="Trouver le commandant Ashlam Valorfist. Son camp de base est situé au camp du Noroît, au nord des montagnes d'Alterac."},
    [5082] = {n="La menace des Tombe-hiver", d="Donova Snowden du Berceau-de-l'Hiver veut que vous tuiez 8 Guides, 8 Protecteurs et 8 Totémiques de la tribu Tombe-hiver.", tgo={{"Guide Tombe-hiver"}, {"Protecteur Tombe-hiver"}, {"Totémique Tombe-hiver"}}},
    [5083] = {n="L'eau de feu de Tombe-hiver", d="Apporter le Flacon d'eau de feu vide à Donova Snowden du Berceau-de-l'Hiver."},
    [5084] = {n="Corrompu", d="Chercher un indice dans le camp des furbolgs Mort-bois, dans le nord de Gangrebois."},
    [5085] = {n="Gelée mystère", d="Aller faire un rapport de vos trouvailles à Donova Snowden."},
    [5092] = {n="Nettoyer le passage", d="Tuer 10 Ecorcheurs Squelettes et 10 Goules écumantes sur la Colline des chagrins.\nRetourner auprès du commandant Ashlam Valorfist au camp du Noroît, dans les Maleterres de l'ouest.", tgo={{"Ecorcheur Squelette"}, {"Goule écumante"}}},
    [5097] = {n="Tout au long des tours de guet", d="À l'aide de la Torche-balise, marquer chaque tour à Andorhal ; il faut se tenir dans l'embrasure de la porte de la tour pour pouvoir la marquer.\nQuand les quatre tours seront marquées, rapporter la Torche-balise au commandant Ashlam Valorfist au camp du Noroît, dans les Maleterres de l'ouest.", tgo={{"Andorhal Tour un"}, {"Andorhal Tour deux"}, {"Andorhal Tour trois"}, {"Andorhal Tour quatre"}}},
    [5149] = {n="Poupée de Pamela", d="Trouver la poupée de Pamela."},
    [5152] = {n="Tante Marlene", d="Parler à Marlene, au sud des ruines d'Andorhal."},
    [5153] = {n="Un étrange historien", d="Apporter l'Alliance de Joseph à Chromie.", objs={"Monument de Joseph Redpath"}},
    [5154] = {n="Les annales de Darrowshire", d="Apporter les Annales de Darrowshire à Chromie, à Andorhal.", objs={"Tome moisi"}},
    [5155] = {n="Les forces de Jaedenar", d="Entrer dans Jaedenar et tuer 4 Molosses de Jaedenar, 4 Gardiens de Jaedenar, 6 Adeptes de Jaedenar, et 6 Sectateurs de Jaedenar avant de retourner auprès de Greta Mosshoof dans Gangrebois.", tgo={{"Molosse de Jaedenar"}, {"Gardien de Jaedenar"}, {"Adepte de Jaedenar"}, {"Sectateur de Jaedenar"}}},
    [5156] = {n="Enquête sur la corruption", d="Trouver et détruire 2 Bêtes d'entropie et 2 Horreurs d'entropie tout en explorant le Val Grêlé. Après avoir vérifié que les cratères à cet endroit sont toujours remplis d'eau corrompue, retourner auprès de Taronn Redfeather dans Gangrebois.", tgo={{"Bête d'entropie"}, {"Horreur d'entropie"}}},
    [5157] = {n="Recueillir de l'eau souillée", d="Amener la Gourde vide au Puits de lune au centre de Jaedenar et la remplir avant de retourner voir Greta Mosshoof dans Gangrebois.", objs={"Le Puits de lune corrompu de Jaedenar"}},
    [5158] = {n="À la recherche de soutien spirituel", d="Apporter l'Eau de Puits de lune corrompue à Islen Waterseer dans les Tarides."},
    [5159] = {n="L'eau purifiée retourne à Gangrebois", d="Apporter l'Eau de Puits de lune purifiée à Greta Mosshoof dans Gangrebois."},
    [5168] = {n="Héros du Darrowshire", d="Apporter le Libram de Davil et le Bouclier Redpath à Carlin Redpath.", objs={"Libram de Davil", "Bouclier de Redpath"}},
    [5181] = {n="Vilains de Darrowshire", d="Rapporter le Crâne d'Horgus et l'Epée brisée de Marduk à Carlin Redpath à la chapelle de l'Espoir de Lumière.", objs={"Crâne d'Horgus", "Epée brisée de Marduk"}},
    [5210] = {n="Frère Carlin", d="Apporter les Annales complètes de Darrowshire à Carlin Redpath dans les Maleterres de l'est."},
    [5211] = {n="Défenseurs de Darrowshire", d="Libérer 15 Esprits de Darrowshire et retourner auprès de Carlin Redpath.", tgo={{"Esprit de Darrowshire"}}},
    [5215] = {n="Les chaudrons du Fléau", d="Parler à la grande prêtresse MacDonnell à la pointe du Noroît, dans les Maleterres de l'ouest."},
    [5216] = {n="Cible : le Champ de Felstone", d="Se rendre au Champ de Felstone dans les Maleterres de l'ouest pour trouver et vaincre le Seigneur du Chaudron qui s'y trouve. Il aura peut-être une clé qui permet d'accéder au chaudron. Il faut se munir de la Bouteille d'échantillon du Champ de Felstone vide pour pouvoir prélever un échantillon des poisons qui sont dans le chaudron.", tgo={{"Seigneur du Chaudron Bilegueule"}}},
    [5217] = {n="Retour au camp du Noroît", d="Apporter une Bouteille du Champ de Felstone remplie à la grande prêtresse MacDonnell au camp du Noroît, dans les Maleterres de l'ouest."},
    [5219] = {n="Cible : les Larmes de Dalson", d="Se rendre aux Larmes de Dalson dans les Maleterres de l'ouest pour trouver et vaincre le Seigneur du Chaudron qui s'y trouve, puis utiliser sa clé pour accéder au chaudron. Il faut se munir de la Bouteille des larmes de Dalson vide pour pouvoir prendre un échantillon des poisons qui sont dans le chaudron.", tgo={{"Seigneur du Chaudron Malvinious"}}},
    [5220] = {n="Retour au camp du Noroît", d="Apporter la Bouteille des Larmes de Dalson remplie à la grande prêtresse MacDonnell au camp du Noroît, dans les Maleterres de l'ouest."},
    [5222] = {n="Cible : le Repaire putride", d="Se rendre au Repaire putride dans les Maleterres de l'ouest pour trouver et vaincre le Seigneur du Chaudron qui s'y trouve, et utiliser sa clé pour accéder au chaudron. Il faut se munir de la Bouteille vide du Repaire putride pour pouvoir récupérer un échantillon des poisons à l'intérieur du chaudron.", tgo={{"Seigneur du Chaudron Razarch"}}},
    [5223] = {n="Retour au camp du Noroît", d="Apporter la Bouteille du Repaire putride remplie à la grande prêtresse MacDonnell au camp du Noroît, dans les Maleterres de l'ouest."},
    [5225] = {n="Cible : la Flétrissure de Gahrron", d="Se rendre à la Flétrissure de Gahrron dans les Maleterres de l'ouest pour trouver et vaincre le Seigneur du Chaudron qui s'y trouve, et utiliser sa clé pour accéder au chaudron. Il faut se munir de la Bouteille vide de la Flétrissure de Gahrron pour pouvoir récupérer un échantillon des poisons à l'intérieur du chaudron.", tgo={{"Seigneur du Chaudron Irâme"}}},
    [5226] = {n="Retour au camp du Noroît", d="Apporter la Bouteille de la Flétrissure de Gahrron remplie à la grande prêtresse MacDonnell au camp du Noroît, dans les Maleterres de l'ouest."},
    [5238] = {n="Mission accomplie !"},
    [5241] = {n="Oncle Carlin", d="Trouver Carlin Redpath."},
    [5244] = {n="Les ruines de Kel'Theril", d="Parler à Jaron Stoneshaper au village de Pluie-d'Etoiles"},
    [5245] = {n="Les Esprits troublés de Kel'Theril", d="Utiliser la Pique de Jaron pour trouver les quatre Fragments de relique des Bien-nés. Les apporter à Aurora Skycaller dans les Maleterres de l'est.", objs={"Fragment de relique de Bien-né"}},
    [5246] = {n="Fragments du passé", d="Trouver les Ecrits sacrés des Bien-nés dans le temple de Zin-Malor à Azshara et les apporter à Aurora Skycaller à la tour du Col du nord, dans les Maleterres de l'est.", objs={"Textes sacrés des Bien-nés"}},
    [5250] = {n="Pluie-d'Etoiles", d="Trouver le village de Pluie-d'Etoiles dans le Berceau-de-l'Hiver et parler à Wynd Nightchaser."},
    [5261] = {n="Eagan le tanneur", d="Parler à Eagan Peltskinner."},
    [5401] = {n="Brevet de l'Aube d'argent"},
    [5541] = {n="Munitions pour Rumbleshot", d="Apporter les Munitions de Rumbleshot à Hegnar Rumbleshot à Dun Morogh.", objs={"Caisse de munitions"}},
    [5542] = {n="Chiens-démons", d="Tuer 20 Chiens pestiférés chétifs, 5 Chiens pestiférés et 5 Chiens pestiférés frénétiques. Retourner voir Tirion Fordring, quand la mission sera terminée.", tgo={{"Chien pestiféré chétif"}, {"Chien pestiféré"}, {"Chien pestiféré frénétique"}}},
    [5543] = {n="Ciel couleur de sang", d="Tuer 30 Chauves-souris pestiférées, puis retourner voir Tirion Fordring.", tgo={{"Chauve-souris pestiférée"}}},
    [5544] = {n="Larve putride", d="Chercher les Larves putrides et les Dévoreurs de la région. Les tuer et récupérer leur viande. Retourner voir Tirion Fordring quand 15 pièces de Chair de Ver putride auront été récupérées.", tgo={{"Larve putride", "Dévoreur putride"}}},
    [5545] = {n="Un sac d'embrouilles", d="Apporter 8 fagots de bois à Raelen au Camp de bûcherons du Val d'est.", objs={"Fagot de bois"}},
    [5601] = {n="Pamela, ma sœur", d="Trouver Pamela Redpath dans le Darrowshire."},
    [5713] = {n="Un tir. Un tué.", d="Protéger la Sentinelle Aynasha, puis parler à Onaeya au poste de Maestra, en Ashenvale."},
    [5742] = {n="Rédemption", d="Écouter ce que Tirion Fordring a à dire.", tgo={{"Tirion Fordring"}}},
    [5762] = {n="Hemet Nesingwary", d="Apporter la Caisse de Kravel à Hemet Nesingwary, à Strangleronce."},
    [5781] = {n="Aux mémoires perdues", d="Aller au caveau de Zaeldarr - situé dans la section la plus au sud des Maleterres de l'est - et récupérer le Marteau de Taelan. Retourner auprès de Tirion Fordring après avoir accompli la mission.", tgo={{"Mercutio Filthgorger"}}},
    [5845] = {n="De l'honneur perdu", d="Se rendre à Valnord, dans la région nord-est des Maleterres de l'est, et récupérer le Symbole de l'honneur perdu. Revenir auprès de Tirion Fordring quand la tâche est accomplie.", objs={"Symbole de l'honneur perdu"}},
    [5846] = {n="L'amour et la famille", d="Voyager jusqu'à l'île de Caer Darrow, dans la région centre-sud des Maleterres, et chercher un indice de l'emplacement du tableau."},
    [5848] = {n="De l'amour et de la famille", d="Se rendre à Stratholme, dans la partie nord des Maleterres. C'est dans le Bastion écarlate que se trouve le tableau De l'amour et de la famille, caché derrière une autre peinture représentant les lunes jumelles.\nRapporter le tableau à Tirion Fordring.", objs={"Peinture inachevée"}},
    [5863] = {n="La base des Cognedunes", d="Andi Lynn de Gadgetzan veut que vous détruisiez la Base des Cognedunes en tuant 10 Brutes Cognedunes, 10 Massacreurs Cognedunes, et Gor'marok le Ravageur.", tgo={{"Brute Cognedune"}, {"Massacreur Cognedune"}, {"Gor'marok le Ravageur"}}},
    [5903] = {n="Une Plaie sur la Croisade", d="Utiliser le Pot de Termites vide sur la Termitière, dans les Maleterres de l'est. Après avoir récupéré 100 Termites des Maleterres, retourner voir Nathaniel Dumah, au camp du Noroît, dans les Maleterres de l'ouest.", objs={"Grande termitière"}},
    [5904] = {n="Une Plaie sur la Croisade", d="Trouver un endroit propice, au centre de la scierie de la Crête du nord, dans les Maleterres de l'ouest, pour placer le Tonneau de Termites des Maleterres."},
    [6001] = {n="Corps et cœur", d="Utiliser la Poussière de lune cénarienne sur la Pierre des séléniens d'Auberdine pour invoquer Lunegriffe. Affronter Lunegriffe, et gagner la force physique et spirituelle qu'il possède.\nQuand cela est fait, parler à Mathrengyl Bearwalker, à Darnassus.", tgo={{"Esprit de Lunegriffe"}}},
    [6004] = {n="Un travail inachevé", d="Tuer deux Médecins écarlates, deux Chasseurs écarlates, deux Magi écarlates et deux Chevaliers écarlates avant de revenir vers Krista Deepshadow dans les Maleterres de l'ouest.", tgo={{"Médecin écarlate"}, {"Chasseur écarlate"}, {"Mage écarlate"}, {"Chevalier écarlate"}}},
    [6021] = {n="Zaeldarr le Banni", d="Apporter la Tête de Zaeldarr au Conservateur Alen, à la chapelle de l'Espoir de Lumière.", tgo={{"Zaeldarr le Banni"}}},
    [6023] = {n="Un travail inachevé", d="Tuer le veneur Radley et le cavalier Durgen, avant de retourner voir Kirsta Deepshadow, dans les Maleterres de l'ouest.", tgo={{"Veneur Radley"}, {"Cavalier Durgen"}}},
    [6024] = {n="L'appel d'Hameya", d="Tuer l'Infiltrateur Hameya. Utiliser sa clé sur le Monticule de poussière, derrière le caveau de Zaeldarr.", tgo={{"Infiltrateur Hameya"}}},
    [6025] = {n="Un travail inachevé", d="Aller dans Hearthglen, et trouver un poste d'observation élevé d'où voir la ville et jauger les forces de la Croisade écarlate, puis retourner voir Kirsta Deepshadow, dans les Maleterres de l'ouest."},
    [6028] = {n="Le rapport de Long-guet", d="Apportez le Rapport de Long-guet à l'officier de l'Aube d'argent Pureheart au Camp du Noroît, dans les Maleterres de l'ouest."},
    [6030] = {n="Le duc Nicholas Zverenhoff", d="Apportez le livre \" Etudes sur la langue des Esprits \" au duc Nicholas Zverenhoff, à la chapelle de l'Espoir de Lumière, dans les Maleterres de l'est."},
    [6063] = {n="Dompter la bête", d="Utiliser le Bâtonnet de domptage pour dompter une Rôdeuse Tissebois. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Dazalar, à Dolanaar.", tgo={{"Rôdeuse Tissebois"}}},
    [6064] = {n="Dompter la bête", d="Utiliser le Bâtonnet de domptage pour dompter un Grand sanglier des rochers. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Grif Wildheart, à Kharanos.", tgo={{"Grand sanglier des rochers"}}},
    [6084] = {n="Dompter la bête", d="Domptez un Léopard des neiges à l'aide du Bâtonnet de domptage. Entraînez-vous puis retournez voir Grif Wildheart à Kharanos.", tgo={{"Léopard des neiges"}}},
    [6085] = {n="Dompter la bête", d="Domptez un ours Griffeglace à l'aide du Bâtonnet de domptage. Entraînez-vous puis retournez voir Grif Wildheart à Kharanos.", tgo={{"Ours Griffeglace"}}},
    [6086] = {n="Entraîner la bête", d="Adressez-vous à Belia Thundergranite à Forgefer."},
    [6101] = {n="Dompter la bête", d="Utiliser le Bâtonnet de domptage pour dompter un Rôdeur sabre-de-nuit. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Dazalar, à Dolanaar.", tgo={{"Rôdeur sabre-de-nuit"}}},
    [6102] = {n="Dompter la bête", d="Utiliser le Bâtonnet de domptage pour dompter un Hurleur Strigid. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Dazalar, à Dolanaar.", tgo={{"Hurleur Strigid"}}},
    [6103] = {n="Entraîner la bête", d="Parler à Jocaste, à l'enclave cénarienne de Darnassus."},
    [6134] = {n="Chasse à l'ectoplasme", d="Apporter 8 Fantôm-o-plasmes et la Caisse d'aimants fantômes à Hornizz Brimbuzzle, en Désolace.", tgo={{"Spectre de centaure"}}},
    [6182] = {n="Le premier et le dernier", d="Parler à Mathias Shaw, dans la vieille ville de Stormwind. Il se trouve dans la caserne."},
    [6183] = {n="Honorer la mort", d="Reparlez à Mathias Shaw, quand vous aurez décidé d'accepter son travail."},
    [6184] = {n="Flint Shadowmore", d="Allez au camp du Noroît, dans les Maleterres de l'ouest, et rencontrez votre contact, Flint Shadowmore."},
    [6185] = {n="Les Maleterres de l'Est", d="Fouillez les Maleterres de l'est pour trouver des indices relatifs au \"Flétrisseur\" et aux agents du SI:7 portés disparus. Si vous trouvez un quelconque Insigne du SI:7, rapportez-le à Flint Shadowmore, au camp du Noroît.", objs={"Restes humains mutilés"}},
    [6341] = {n="Le don de Teldrassil", d="Apporter la Collection de Nessa à Vesprystus."},
    [6342] = {n="Vol vers Auberdine", d="Prenez un hippogryphe vers Auberdine chez le maître des hippogryphes Vesprystus, puis apportez la Collection de Nessa à Laird."},
    [6343] = {n="Retourner à Nessa", d="Réponse de Laird à Nessa Shadowsong."},
    [6344] = {n="Nessa Shadowsong", d="Parler à Nessa Shadowsong."},
    [6387] = {n="L'honneur des étudiants", d="Apportez la Liste de Brock à Thorgrum Borrelson à Thelsamar."},
    [6388] = {n="Gryth Thurden", d="Apportez les Pioches d'honneur à Gryth Thurden à Forgefer."},
    [6389] = {n="Une Plaie sur la Croisade", d="Libérez les Termites des Maleterres dans la scierie de la Crête du nord, puis retournez voir Nathaniel Dumah, au camp du Noroît, dans les Maleterres de l'ouest, avec le Tonneau de Termites des Maleterres."},
    [6391] = {n="Voyage vers Forgefer", d="Acheter un billet de gryphon pour Forgefer, auprès du Maître des gryphons, Thorgrum Borrelson, puis apporter la Liste de Brock à Golnir Bouldertoe, à Forgefer."},
    [6392] = {n="Retourner vers Brock", d="Acheter un billet de gryphon pour Thelsamar, auprès du Maître des gyphons Gryth Thurden, puis apporter les Pioches d'honneur à Brock Stoneseeker, à Thelsamar."},
    [6603] = {n="Troubles au Berceau-de-l'Hiver", d="Trouver Donova Snowden, à côté des sources chaudes du Berceau-de-l'Hiver."},
    [6604] = {n="Les Indomptables enragés", d="Parler à Jaron Stoneshaper, au village de Pluie-d'Etoiles."},
    [7383] = {n="La couronne de la Terre", d="Remplir la Fiole d'améthyste et la rapporter à Corithras Moonrage à Dolanaar.", objs={"Puits de lune de la Clairière de l'Oracle"}},
    [7701] = {n="ON RECHERCHE : Surveillant Maltorius", d="Loin dans les profondeurs de la Fosse aux scories dans le Chaudron, dans la Gorge des Vents brûlants, vous trouverez le nain traître du clan Sombrefer répondant au nom de surveillant Maltorius.\nTuez le surveillant Maltorius et prenez sa tête. Apportez-la au capitaine de guet Lolo Longstriker dans la Gorge des Vents brûlants pour la récompense.", tgo={{"Surveillant Maltorius"}}},
    [7722] = {n="Le Flux embrasé", d="Quelque part dans la Fosse aux scories du Chaudron, vous trouverez les Plans secrets : Flux embrasé dérobés par le surveillant Maltorius. Trouvez ces plans et rapportez-les au Maître forgeron Burninate dans la gorge des Vents brûlants.", objs={"Plans secrets : Flux embrasé"}},
    [7723] = {n="Maudits gros doigts", d="Hansel Heavyhands veut que vous tuiez 20 Golems de guerre lourds.\nLes golems de guerre lourds errent dans les régions qui entourent le Chaudron dans la Gorge des Vents brûlants. Quand vous en aurez tué assez, revenez voir Hansel dans la Gorge des Vents brûlants.", tgo={{"Golem de guerre lourd"}}},
    [7724] = {n="Une menace incandescente", d="Hansel Lourdemains veut que vous tuiez 20 araignées de lave incendiaires dans la gorge des Vents brûlants. Vous pouvez trouver les araignées de lave incendiaires dans les plateaux et les mares de lave de la gorge des Vents brûlants.\nRevenez voir Hansel Lourdemains dans la gorge des Vents brûlants quand vous aurez tué assez de araignées de lave incendiaires.", tgo={{"Araignée de lave incendiaire"}}},
    [7727] = {n="Incendosaures ? N'importosaures, plutôt", d="Hansel Heavyhands veut que vous tuiez 20 Incendosaures.\nOn peut les trouver dans les bassins de lave de la Fosse aux scories, qui occupe une partie du Chaudron de la gorge des Vents brûlants.\nRetournez voir Hansel Heavyhands dans la gorge des Vents brûlants lorsque vous aurez tué suffisamment d'Incendosaures.", tgo={{"Incendosaure"}}},
    [7728] = {n="OBJETS VOLES : Tuyère et longue-vue", d="Trouvez la Tuyère de forge et la Longue-vue du guetteur et rapportez-les au sous-chef Scrange dans la gorge des Vents brûlants.\nLes seules informations dont vous disposez sur ces objets sont les suivantes : ils ont été dérobés par les nains Sombrefer, la Tuyère de forge est un outil utilisé par les forgerons et la Longue-vue du guetteur est un outil de surveillance inestimable pour les guetteurs.", tgo={{"Forge-vapeur Sombrefer"}, {"Guetteur Sombrefer"}}},
    [7729] = {n="OFFRE D'EMPLOI : Réduire la concurrence", d="Tuez 15 Sous-chefs Sombrefer et 15 Esclavagistes Sombrefer. Revenez voir le sous-chef Scrange dans la gorge des Vents brûlants quand vous aurez accompli cette tâche.", tgo={{"Sous-chef Sombrefer"}, {"Esclavagiste Sombrefer"}}},
    [7733] = {n="Qualité améliorée", d="Fournir 10 Peaux de yéti Griffe Féroce à Pratt McGrubben au bastion de Feathermoon, en Feralas.", tgo={{"Yéti Griffe féroce", "Ancien Griffe féroce", "Griffe féroce enragé", "Griffe farouche patibulaire"}}},
    [7735] = {n="Une peau de yéti en parfait état", d="Apporter la Peau de yéti en parfait état à Pratt McGrubben au bastion de Feathermoon, en Feralas."},
    [7791] = {n="Un don de laine", d="Utiliser/ramasser : Granit d'Alterac, Coffre en morceaux, Coffre en morceaux", objs={"Granit d'Alterac", "Coffre en morceaux", "Coffre en morceaux"}},
    [7793] = {n="Un don de soie", d="Utiliser/ramasser : Granit d'Alterac, Coffre en morceaux, Coffre solide", objs={"Granit d'Alterac", "Coffre en morceaux", "Coffre solide"}},
    [8360] = {n="Danser pour du massepain", d="Utilisez l'emote /danser devant l'aubergiste Pala, et vous recevrez en échange du massepain de Thunder Bluff !", tgo={{"Pala l'aubergiste"}}},
    [8365] = {n="Ohé, des chapeaux de pirate !", d="La Modiste arrogante veut que vous lui rapportiez 20 Chapeaux de pirate des Mers du sud au port Gentepression, en Tanaris.", tgo={{"Pirate des Mers du sud", "Flibustier des Mers du sud", "Portefaix des Mers du sud", "Bretteur des Mers du sud", "Andre Barbe-en-feu", "Kregg Keelhaul"}}},
    [8460] = {n="Allié des Grumegueules", d="Grifleur veut que vous prouviez votre valeur en tuant 6 Guerriers Mort-bois, 6 Guides Mort-bois et 6 Jardiniers Mort-bois. Lorsque ce sera fait, retournez le voir dans le sud de Gangrebois, près du Sanctuaire d'émeraude.", tgo={{"Guerrier Mort-bois"}, {"Guide Mort-bois"}, {"Jardinier Mort-bois"}}},
    [8461] = {n="Les Mort-bois du nord", d="Nafien veut que vous tuiez 6 Protecteurs Mort-bois, 6 Vengeurs Mort-bois et 6 Chamans Mort-bois. Ensuite, retournez le voir dans le nord de Gangrebois, près de l'entrée du repaire des Grumegueules.", tgo={{"Protecteur Mort-bois"}, {"Vengeur Mort-bois"}, {"Chaman Mort-bois"}}},
    [8462] = {n="Parler à Nafien", d="Suivre la route principale de Gangrebois vers le nord et parler à Nafien le furbolg. Il monte la garde à côté de l'entrée du repaire des Grumegueules."},
    [8464] = {n="Les Tombe-hiver s'agitent", d="Salfa voudrait que vous tuiez 8 Chamans Tombe-hiver, 8 Protecteurs Tombe-hiver et 8 Ursas Tombe-hiver. Salfa se trouve juste à l'extérieur de l'entrée du repaire des Grumegueules, au Berceau-de-l'hiver.", tgo={{"Chaman Tombe-hiver"}, {"Protecteur Tombe-hiver"}, {"Ursa Tombe-hiver"}}},
    [86574] = {n="Ravitaillement des Serres-Rocheuses", d="Récupérez 6 fournitures des Serres-Rocheuses sur des wyvernes aile-fières, et apportez-les à l'aubergiste Faralia.", tgo={{"Jeune Aile-fière", "Wyverne Aile-fière", "Chasseresse céleste Aile-fière", "Concubine Aile-fière", "Patriarche Aile-fière", "Freewind Post Wyvern"}}},
    [86758] = {n="Remuer le couteau dans la plaie", d="Terrassez le crocilisque Daguecroc et rapportez le couteau de Marek.", tgo={{"Daguecroc"}}},
    [87288] = {n="Fourrures soyeuses de sabre-de-nuit", d="Rapportez 6 $fourrures soyeuses de sabre-de-nuit à Aldia.", tgo={{"Sabre-de-nuit sauvage"}}},
    [87760] = {n="Plongeur sacré", d="Trouvez une maîtresse des bêtes tempécaille, terrassez-la et rapportez son bâtonnet de domination profonde.", tgo={{"Maîtresse des bêtes tempécaille"}}},
    [91723] = {n="Des instruments délicats", d="Tuez 8 géomanciens kobolds à la mine Veine-de-jaspe, puis retournez voir Hamish Bergwort à la tour d'Azora.", tgo={{"Géomancien kobold"}}},
    [91732] = {n="De l'acier de qualité", d="Collectez 4 outils de minage dans la mine Veine-de-jaspe, puis retournez voir Hagar Lowe au camp de bûcherons du val d'Est.", objs={"Outils de minage"}},
    [91733] = {n="En aval", d="Collectez la hache détrempée, la scie détrempée et la boîte à outils détrempée échouées en aval du camp de bûcherons du val d'Est, puis retournez voir Ormin Pelford.", objs={"Hache détrempée", "Scie détrempée", "Boîte à outils détrempée"}},
    [91740] = {n="La tête de Coassie", d="Apportez la tête de Coassie à Merell Ross à la tour de la Crête."},
    [91741] = {n="Un livre grignoté", d="Rapportez le livre au frère Paxton."},
    [91743] = {n="Rongeurs retors", d="Récupérez 8 livres dérobés sur des Kobolds de la vallée de Comté-du-Nord et rapportez-les au frère Paxton.", tgo={{"Vermine kobold", "Travailleur kobold", "Ouvrier kobold"}}},
    [91745] = {n="Consultant en minage", d="Allez voir Kelsey Fond devant la mine de la Crête aux échos, dans la vallée de Comté-du-Nord."},
    [91752] = {n="Un peu de recul", d="Récupérez un sac de livres « d'images » auprès du trouve-qui-brille Narf et rapportez-le au maréchal McBride, devant l'abbaye de Comté-du-Nord.", tgo={{"Trouve-qui-brille Narf"}}},
    [91753] = {n="Une leçon enchanteresse", d="Kitta Ventefeu de la tour d'Azora vous demande de récupérer 3 résidus lumineux.\nVous pourrez obtenir des résidus lumineux en désenchantant les effigies en cire rudimentaires abandonnées par les géomanciens kobolds."},
    [91758] = {n="Suivez ce Kobold !", d="Allez voir Tordrin Tigelame près de l'écurie derrière l'abbaye de Comté-du-Nord."},
    [91772] = {n="Chut, on chasse le Kobold", d="Suivez les traces des Kobolds avec le kit de pistage et allez avertir le maréchal Dughan, à Comté-de-l'Or.", objs={"Kobold Tracks"}},
    [91775] = {n="Restitution de livres", d="Trouvez 6 livres perdus et « Les Joyeux Élémentaires », et rapportez-les au maréchal Dughan.", tgo={{"Nimsy"}, {"Mineur kobold", "Tunnelier kobold"}}},
    [91777] = {n="Des livres rares", d="Récupérez « La Géomancie pour les jeunes sorciers curieux » et « Petit manuel des arcanes : La Magie en toute simplicité », puis rapportez-les au frère Paxton, à l'abbaye de Comté-du-Nord.", tgo={{"Géosculpteur Yip", "Géomancien kobold"}, {"Mère Croc", "Géomancien kobold"}}},
    [92124] = {n="Inventaire des livres", d="Allez voir Daniel, l'assistant du frère Paxton à la bibliothèque."},
    [92415] = {n="N'oublie pas que je t'aime", d="Apportez la lettre tachée de sang à la directrice de l'orphelinat Rossignol, à Hurlevent."},
    [92460] = {n="Il est temps de grandir", d="Parlez à Rorian le Cherchejour dans le bosquet de Thendal."},
    [92461] = {n="Équilibre et harmonie", d="Éliminez 8 jeunes vuldrènes dans le bosquet de Thendal.", tgo={{"Jeune vuldrène"}}},
    [92462] = {n="Enquête sur l'infestation", d="Éliminez 8 mouches-cirrus agaçantes dans le bosquet de Thendal.", tgo={{"Mouche-cirrus agaçante"}}},
