    [96101] = {n="Les grands espaces sauvages", d="Asseyez-vous près du feu de camp basique de Raan et attendez de recevoir l'amélioration Repos amplifié.", objs={"Basic Campfire"}},
    [96137] = {n="Dague d'Ira", d="Terrassez 10 jeunes ravageurs noirs et 7 ravageurs noirs, puis retournez voir Sirra Von'Indi à Sombre-Comté pour de plus amples informations.", tgo={{"Jeune Ravageur noir"}, {"Ravageur noir"}}},
    [96138] = {n="Arc de Merrick", d="Terrassez 8 guerriers Brisepoing et 4 sous-chefs Brisepoing, puis retournez voir Sirra Von'Indi à Sombre-Comté pour en savoir plus.", tgo={{"Guerrier Brisepoing"}, {"Sous-chef Brisepoing"}}},
    [96139] = {n="La famille Valor", d="Fouillez la Colline-aux-Corbeaux à la recherche de tout élément intéressant, puis retournez voir Sirra Von'Indi à Sombre-Comté.", objs={"Memory of Valor"}},
    [96390] = {n="Étouffer le mal dans l'œuf", d="Tuez 10 espions sombrefer à Dun Morogh.", tgo={{"Espion Sombrefer"}}},
    [96391] = {n="La carte souterraine", d="Remettez la carte sombrefer au terre-voyant Farsen, à Dun Morogh."},
    [96392] = {n="Le guet de Farsen", d="Parlez au terre-voyant Farsen et demandez-lui de vous prêter sa double vue pour observer la menace des Sombrefer.", tgo={{"Terre-voyant Farsen"}}},
    [96393] = {n="Incursion dans le Vieux Forgefer", d="Pénétrez dans la salle des Thanes, sous le Vieux Forgefer, et emparez-vous de la tête de Durgen Mornemartel."},
    [96394] = {n="Les morts sans repos", d="Tuez 15 apparitions enragées et 10 âmes tourmentées, puis accordez le repos à l'esprit de Courbenclume."},
    [96395] = {n="Une rancune ancestrale", d="Apaisez l'esprit de Faldrim Courbenclume, puis retournez voir la domestique fantomatique dans la salle des Thanes."},
    [96403] = {n="Précieux héritages", d="Récupérez 8 héritages nains dans la salle des Thanes.", objs={"Héritage nain"}},
    [96606] = {n="Les grands espaces sauvages", d="Asseyez-vous près du feu de camp basique de Lyreena et attendez de recevoir l'amélioration Repos amplifié.", objs={"Basic Campfire"}},
    [96608] = {n="Les grands espaces sauvages", d="Asseyez-vous près du feu de camp basique d'Eric et attendez de recevoir l'amélioration Repos amplifié.", objs={"Basic Campfire"}},
