    [96634] = {n="Introduction au camping : la cuisine", d="Parlez à Zarrin, à Dolanaar, pour apprendre à cuisiner.", tgo={{"Zarrin"}}},
    [96638] = {n="L'aventurier", d="Parlez à Raan Aile-sauvage près de Shen'dar."},
    [96646] = {n="Introduction au camping : la cuisine", d="Parlez à Zerril Douce-Brise à Shen'dar pour apprendre à cuisiner.", tgo={{"Zerril Douce-Brise"}}},
    [97236] = {n="Crochet de Githyiss", d="Apportez le crochet de Githyiss à quelqu'un d'Aldrassil qui s'intéresse tout particulièrement à l'étude des araignées."},
    [97277] = {n="Grund et Gozwin", d="Trouvez le camp de Grund et Gozwin dans les collines du nord-ouest. Récupérez le journal de mécano de Gozwin et tuez le léopard des neiges rôdeur.", tgo={{"Léopard des neiges rôdeur"}, {}}, objs={"Journal de mécano de Gozwin"}},
    [97894] = {n="Affaires à Auberdine", d="Prenez des nouvelles de Gorbold Main-d'acier à Auberdine, à Sombrivage.\nBorgus a parlé d'un bateau, au quai le plus au sud du port de Hurlevent, qui peut vous y emmener."},
    [97914] = {n="Vers de nouveaux horizons", d="Remettez la lettre de Thundris à Baros Alexston, à Hurlevent.\nThundris a mentionné un navire d'Auberdine qui peut vous y conduire."},
    [97919] = {n="Introduction au camping : les premiers soins", d="Parlez à Michelle Belle, à Comté-de-l'Or, pour apprendre à fabriquer un objet de camping propre à votre métier une fois que vous vous serez fait la main.", tgo={{"Michelle Belle"}}},
    [97924] = {n="Introduction au camping : le dépeçage", d="Parlez à Helene Tannepeau, à Comté-de-l'Or, pour apprendre à fabriquer un objet de camping propre à votre métier une fois que vous vous serez fait la main.", tgo={{"Helene Peltskinner"}}},
