    [97942] = {n="Introduction au camping : les premiers soins", d="Parlez à Byancie, à Dolanaar, pour apprendre à fabriquer un objet de camping propre à votre métier une fois que vous vous serez fait la main.", tgo={{"Byancie"}}},
    [97949] = {n="Introduction au camping : le dépeçage", d="Parlez à Radnaal Tissecrin, sur la route qui relie Dolanaar à Darnassus, pour apprendre à fabriquer un objet de camping propre à votre métier une fois que vous vous serez fait la main.", tgo={{"Radnaal Maneweaver"}}},
    [97971] = {n="Introduction au camping : le dépeçage", d="Parlez à Mendalass Racommode, à Shen'dar, pour apprendre à fabriquer un objet de camping propre à votre métier une fois que vous vous serez fait la main.", tgo={{"Mendalass Racommode"}}},
