    [97979] = {n="La déesse pourvoyeuse", d="Lancez Lumière d'Elune et Camouflage dans l'ombre."},
    [98013] = {n="Forces croissantes", d="Éliminez 12 myrmidons tempécailles, 8 ensorceleuses tempécailles et 6 guerriers tempécailles pour Arbal, au bosquet des Anciens.", tgo={{"Myrmidon Tempécaille"}, {"Ensorceleuse Tempécaille"}, {"Guerrier Tempécaille"}}},
    [98025] = {n="ON RECHERCHE : Jai'vhanel", d="Trouvez Jai'vhanel et terrassez-la, puis récupérez l'une de ses plumes. La chouette noire a été aperçue pour la dernière fois au nord des ruines d'Ameth'Aran, près du pied de la montagne. Signalez la mort de Jai'vhanel à la sentinelle Glynda Nal'Shea, à Auberdine.", tgo={{"Jai'vhanel"}}},
    [98027] = {n="Le collier de lune resplendissante", d="Apportez le collier de lune resplendissante à Maliynn à Astranaar."},
    [98042] = {n="Rira bien qui rira le dernier", d="Obtenez un œil sans pareil auprès d'un disciple ou d'un nervi du Crépuscule, au Glaive du Maître à Sombrivage, puis trouvez quelqu'un à Auberdine qui accepte de le prendre.", tgo={{"Disciple du crépuscule", "Nervi du crépuscule"}}},
    [98046] = {n="La couronne de la Terre", d="Rapportez le réceptacle asséché à Lariia, au temple de la Lune, à Darnassus."},
    [98065] = {n="La couronne de la Terre", d="Rapportez les restes de puits de lune à Tyrande Murmevent, au temple de la Lune, à Darnassus."},
    [98067] = {n="Regard des Sentinelles", d="Placez des hiboux sentinelles à l'entrée des profondeurs du fort Cénarien, à la banque de Darnassus, à l'auberge de la terrasse des Artisans et aux portes de la ville pour la sentinelle Dalia Lamesoleil au temple de la Lune, à Darnassus.", tgo={{"Credit"}, {"Credit"}, {"Credit"}, {"Credit"}}},
    [98071] = {n="Échanges brassicoles", d="Apportez les bouteilles de cépage de Ruissautomne à Dun Garok, au sud-est des contreforts de Hautebrande, puis revenez avec un sac de houblon artisanal."},
    [98072] = {n="Crocos des cieux", d="Récupérez 8 écailles cramoisies immaculées, puis apportez-les à James Halloran, au port de Menethil.", tgo={{"Dragonnet rouge", "Dragonnet égaré", "Dragonnet crache-flammes", "Dragonnet cramoisi"}}},
    [98189] = {n="Rapporter la statuette", d="Apportez la statuette de Menethil au capitaine Rudepoing, au donjon de Menethil."},
