    [98191] = {n="Proche de la famille", d="Apportez la statuette de Menethil au seigneur Grayson Brisombre, à la cathédrale de la Lumière."},
    [98197] = {n="Butin de guerre", d="Récupérez 6 morceaux de bois de construction de Khaz Modan et 30 unités de fer de Khaz Modan au port de Menethil pour Valstag Gueule-de-fer.", objs={"Bois de construction de Khaz Modan", "Fer de Khaz Modan"}},
    [98208] = {n="Fleur des cieux", d="Récupérez Nord'el pour Sylessa Murmesoir, au port de Menethil."},
    [98221] = {n="Tiré des cendres", d="Le capitaine Rudepoing du donjon de Menethil vous demande de détruire 4 plans d'attaque dans le campement de Hargnecroc."},
    [98245] = {n="Travail d'aiguille tranchegueule", d="Obtenez 10 incisives de tranchegueule pour Howin Genteplume.", tgo={{"Tranchegueule des hautes-terres", "Ancien tranchegueule"}}},
    [98246] = {n="Période de disette", d="Obtenez 12 œufs de tranchegueule en parfait état pour Howin Genteplume."},
    [98282] = {n="Dangers alchimiques", d="Procurez-vous une glande de traqueur intacte au rocher de Thelgen, et apportez-la à Caitlin Grassman, au port de Menethil.", tgo={{"Traqueuse sanguine", "Traqueuse des grottes"}}},
    [98319] = {n="Sécuriser la montagne", d="Trouvez le montagnard Cornélius dans l'antre Gris pour la montagnarde Gretchen.", tgo={{"Montagnard Cornélius"}}},
    [98321] = {n="Cargaison de Flammesilex", d="Récupérez 8 cargaisons de Flammesilex à l'antre Gris pour Tongus Flammesilex, à Kharanos.", objs={"Cargaison de Flammesilex"}},
    [98322] = {n="Sécuriser la montagne", d="Allez voir la montagnarde Gretchen à l'ouest de Kharanos."},
    [98323] = {n="Sécuriser la montagne", d="Apportez le rapport de la montagnarde Gretchen à Senir Blanchebarbe, à Kharanos."},
    [98386] = {n="La scierie d'Alther", d="Éliminez 12 grandes tarentules et détruisez 6 œufs de tarentule à la scierie d'Alther, dans les Carmines, pour aider le contremaître Oslow.", objs={"Tarantula Egg"}},
    [98387] = {n="Barricade rochenoire", d="Rapportez 8 armes volées et 10 fournitures de Rochenoire au maréchal Marris de Comté-du-Lac.", objs={"Weapon Rack", "Arme volée", "Meat Haunch", "Tonneau d'eau", "Fournitures de Rochenoire"}},
