    [98417] = {n="La piste de la vengeance", d="Maseara Lune-d'Automne vous demande de fouiller la région située à l'ouest du Chant des forêts, parmi les démons de Satyrnaar. À votre retour, faites-lui part de tout indice concernant son époux, Kurothel.", objs={"Kurothel's Knapsack"}},
    [98423] = {n="Le traité d'entente", d="Remettez le traité de l'entente à Magni Barbe-de-Bronze, à Forgefer."},
    [98461] = {n="Amour non partagé", d="Apportez la note de Hollee à Tarrel Tisseroche près du port de Menethil, dans les Paluns."},
    [98463] = {n="Le sujet de toutes les conversations", d="Rendez visite à Nixxrax Razlebock à la taverne du Loup de mer, à Baie-du-Butin, dans la vallée de Strangleronce."},
